<script lang="ts">
 import {onMount,tick} from 'svelte';
 import {Plus,ArrowLeft,Download,FileText,Search,RefreshCw,Trash2} from '@lucide/svelte';
 import {api,uploadTo,dateISO} from './api';
 import {enter} from './motion';
 import EnquiryFields from './EnquiryFields.svelte';
 import {enquiryFields,fabricFields,costFields,calcLabels} from './enquiryFields';
 import type {Row} from './types';
 let {companies,company,dirty=$bindable(false)}:{companies:Row[];company:string;dirty?:boolean}=$props();
 let data:Row|null=$state(null),detail:Row|null=$state(null),form:Row=$state({}),mode=$state(''),busy=$state(false),error=$state(''),notice=$state(''),search=$state(''),status=$state('All'),review=$state(''),category=$state('Buyer email'),proofOrder=$state(''),preview:Row|null=$state(null),past:Row|null=$state(null);
 let root:HTMLElement; let registerReturn='enquiry-new',formReturn='';
 async function focusView(id:string){await tick();(root?.querySelector('#'+id) as HTMLElement|null)?.focus()}
 async function back(){detail=null;past=null;error='';notice='';await focusView(registerReturn)}
 const ref=(id:number)=>'EQ-'+String(id).padStart(6,'0');
 const booking=(id:number)=>'BK-'+String(id).padStart(6,'0');
 const qty=(rows:Row[])=>rows.reduce((s,r)=>s+Number(r.quantity||0),0);
 const num=(v:unknown,d=4)=>Number(v||0).toLocaleString('en-IN',{maximumFractionDigits:d});
 const costOrder=['required_metres','target_consumption','kg_metre','fabric_price_metre','sgst_metre','cgst_metre','landed_metre','fabric_per_piece','itemised_cost','base_cost','rejection','finance','overhead','margin','before_commission','commission','cost_per_piece','total_cost','agreed_sale_net','sale_sgst','sale_cgst','agreed_sale_gross'];
 const costEntries=(value:Row)=>costOrder.filter(k=>value[k]!=null).map(k=>[k,value[k]]);
 const dates=(v:string)=>v?new Date(v.slice(0,10)+'T12:00:00').toLocaleDateString('en-GB'):'—';
 const currentCompany=()=>Number(company||companies[0]?.id||0);
 let records=$derived.by(()=>(data?.records||[]).filter((r:Row)=>(!company||Number(company)===r.company_id)&&(status==='All'||r.status===status)&&(!search||[ref(r.id),r.booking_number?booking(r.booking_number):'',r.buyer_name,r.profile.brand,r.profile.buyer_style,r.merchant].join(' ').toLowerCase().includes(search.toLowerCase()))));
 let total=$derived(qty(form.colours||[]));
 let title=$derived(mode==='new'?'New enquiry':mode==='edit'?'Edit enquiry':mode==='fabric'?'Fabric response':mode==='cost'?'Open costing':mode==='review'?'MD review correction':mode==='order'?'Create production PO':'');
 let editable=$derived.by(()=>['Draft','Costing','Changes requested'].includes(detail?.record.status));
 let proofOnly=$derived.by(()=>detail?.record.status==='Booked');
 let canAttach=$derived.by(()=>data?.can_documents&&(['Draft','Fabric requested','Costing','Changes requested'].includes(detail?.record.status)||proofOnly&&data?.can_fabric&&data?.supplier_details));
 async function run(work:()=>Promise<void>){if(busy)return;busy=true;error='';try{await work()}catch(e){error=(e as Error).message}finally{busy=false}}
 async function load(){data=await api('/enquiries')}
 onMount(()=>{run(load)});
 function options(key:string){const cid=Number(form.company_id||detail?.record.company_id||currentCompany());return [...new Set([...(data?.defaults?.[key]||[]),...(data?.options||[]).filter((o:Row)=>o.company_id===cid&&o.kind===key).map((o:Row)=>o.label)])] as string[]}
 async function addOption(key:string,label:string){await api('/enquiry-options',{company_id:Number(form.company_id||detail?.record.company_id),kind:key,label});await load()}
 async function open(id:number){registerReturn='enquiry-open-'+id;await run(async()=>{detail=await api('/enquiries/'+id);review='';past=null;notice='';mode='';dirty=false;category=data?.can_create?'Buyer email':'Supplier quotation';await focusView('enquiry-detail-title')})}
 function fresh(){if(!company&&companies.length>1){error='Select a workspace company before creating an enquiry.';return}error='';notice='';form={company_id:currentCompany(),buyer_id:'',material_id:'',development_id:'',profile:{sale_type:'Export',enquiry_type:'Booking enquiry',garment_currency:'USD',fabric_status:'To be purchased'},colours:[{colour:'',buyer_colour_code:'',quantity:1}]};mode='new';dirty=true;formReturn='enquiry-new';focusView('enquiry-form-title')}
 function edit(kind:string){formReturn='enquiry-edit-'+kind;form=structuredClone($state.snapshot(detail!.record));form.costing={components:[],currency:form.profile.garment_currency||'USD',...form.costing};form.fabric={unit:'MTR',currency:'USD',purchase_type:'Import',response_date:dateISO(),...form.fabric};form.note='';if(kind==='order'){const used=detail!.orders.filter((o:Row)=>o.approval!=='Rejected').reduce((s:number,o:Row)=>s+o.quantity,0);form.po='';form.quantity=qty(form.colours)-used;form.due_date=form.profile.garment_delivery_date;form.product=['Suits','Trousers','Shirts','General'].includes(form.profile.product)?form.profile.product:'General'}mode=kind;dirty=true;preview=null;error='';notice='';focusView('enquiry-form-title')}
 function closeForm(){if(busy)return;if(dirty&&!window.confirm('Discard the unsaved changes?'))return;mode='';dirty=false;error='';preview=null;focusView(formReturn)}
 function changeStyle(){const s=data?.styles.find((s:Row)=>s.id===Number(form.development_id));if(!s)return;const p=s.profile;form.profile={...form.profile,buyer_style:p.style_name||form.profile.buyer_style,product:p.product||form.profile.product,season:p.season||form.profile.season,et_reference:s.code};if(s.material_ids?.length)form.material_id=s.material_ids[0]}
 async function save(e:SubmitEvent){e.preventDefault();await run(async()=>{let result:Row;
  if(mode==='new'||mode==='edit')result=await api('/enquiries'+(form.id?'/'+form.id:''),{action:'save',company_id:Number(form.company_id),buyer_id:Number(form.buyer_id),development_id:Number(form.development_id||0),material_id:Number(form.material_id||0),profile:form.profile,colours:form.colours,version:form.version});
  else if(mode==='order'){await api('/enquiries/'+form.id+'/orders',{version:form.version,po:form.po,quantity:form.quantity,product:form.product,due_date:form.due_date});result={id:form.id}}
  else result=await api('/enquiries/'+form.id,{version:form.version,action:mode==='cost'?'costing':mode==='review'?'review_edit':'fabric',fabric:form.fabric,costing:form.costing,profile:form.profile,note:form.note});
  mode='';dirty=false;preview=null;detail=await api('/enquiries/'+result.id);await load();notice='Saved. The change is recorded in the enquiry history.';await focusView('enquiry-detail-title');
 })}
 async function act(action:string){await run(async()=>{await api('/enquiries/'+detail!.record.id,{action,version:detail!.record.version,note:review});detail=await api('/enquiries/'+detail!.record.id);await load();review='';notice=action==='book'?'Booking generated. Production POs can now be linked.':'Enquiry updated.';await focusView('enquiry-detail-title')})}
 async function calculate(){await run(async()=>{preview=(await api('/enquiries/'+form.id+'/preview',{costing:form.costing})).calculation})}
 async function upload(event:Event){const input=event.target as HTMLInputElement;const files=Array.from(input.files||[]);await run(async()=>{for(const file of files)await uploadTo('/enquiries/'+detail!.record.id+'/files?category='+encodeURIComponent(proofOnly?'Purchase proof':category)+(proofOnly?'&order_id='+proofOrder:''),file);detail=await api('/enquiries/'+detail!.record.id);notice='Documents attached.'});input.value=''}
 async function history(id:number){await run(async()=>{past=await api('/enquiry-history/'+id)})}
 function arrival(f:Row){if(!f.order_confirmed_date)return '';const day=new Date(f.order_confirmed_date+'T12:00:00Z');day.setUTCDate(day.getUTCDate()+Number(f.ex_mill_days||0)+Number(f.transit_days||0));return day.toISOString().slice(0,10)}
 function beforeUnload(e:BeforeUnloadEvent){if(dirty){e.preventDefault();e.returnValue=''}}
</script>
<svelte:window onbeforeunload={beforeUnload}/>
<section class="enquiries" bind:this={root}>
 {#if mode}
 <form class="enquiry-editor" oninput={()=>preview=null} onsubmit={save} use:enter={mode}>
  <header class="enquiry-heading"><div><h2 id="enquiry-form-title" tabindex="-1">{title}</h2>{#if form.id}<p>{ref(form.id)} · {form.buyer_name}</p>{/if}</div><button type="button" class="button secondary" disabled={busy} onclick={closeForm}>Close</button></header>
  <div class="editor-body">
   {#if error}<p class="form-error" role="alert">{error}</p>{/if}
   {#if mode==='new'||mode==='edit'}
    <div class="link-fields"><label>Buyer<select bind:value={form.buyer_id} required disabled={busy||!!form.id} onchange={()=>{form.development_id='';form.material_id=''}}><option value="">Choose buyer</option>{#each (data?.buyers||[]).filter((b:Row)=>b.company_id===Number(form.company_id)) as b}<option value={b.id}>{b.name}</option>{/each}</select></label>
    <label>Approved ET / EST style<select bind:value={form.development_id} disabled={busy} onchange={changeStyle}><option value="">New / unlinked style</option>{#each (data?.styles||[]).filter((s:Row)=>s.company_id===Number(form.company_id)&&(!s.buyer_id||s.buyer_id===Number(form.buyer_id))) as s}<option value={s.id}>{s.code} · {s.profile.style_name}</option>{/each}</select></label>
    <label>ETF / ESF fabric<select bind:value={form.material_id} disabled={busy}><option value="">Fabric to be identified</option>{#each (data?.materials||[]).filter((m:Row)=>m.company_id===Number(form.company_id)) as m}<option value={m.id}>{m.code}</option>{/each}</select></label></div>
    <EnquiryFields fields={enquiryFields.filter(f=>form.profile.sale_type==='Local'?f.key!=='lut_number':!['sale_sgst_percent','sale_cgst_percent'].includes(f.key))} bind:values={form.profile} {options} {busy} onadd={addOption}/>
    <div class="section-heading"><div><h3>Colours & quantities</h3><p>Add one row for each colour. Totals update automatically.</p></div><button class="button secondary" type="button" disabled={busy||form.colours.length>=100} onclick={()=>form.colours.push({colour:'',buyer_colour_code:'',quantity:1})}><Plus size={16}/>Add colour</button></div>
    {#each form.colours as c,i}<div class="colour-row"><label>Colour {i+1}<input bind:value={c.colour} maxlength="150" required disabled={busy}/></label><label>Buyer colour code<input bind:value={c.buyer_colour_code} maxlength="80" disabled={busy}/></label><label>Quantity (pieces)<input type="number" min="1" max="10000000" step="1" bind:value={c.quantity} required disabled={busy}/></label><div class="metres"><span>Fabric required</span><strong>{num(Number(c.quantity||0)*Number(form.profile.consumption||0),3)} m</strong></div><button class="button secondary" type="button" aria-label={'Remove colour '+(i+1)} disabled={busy||form.colours.length===1} onclick={()=>form.colours.splice(i,1)}><Trash2 size={17}/></button></div>{/each}
    <div class="total-strip"><span>{form.colours.length===1?'Single colour':form.colours.length+' colours'}</span><strong>{num(total,0)} pieces</strong><strong>{num(total*Number(form.profile.consumption||0),3)} metres required</strong></div>
   {:else if mode==='fabric'}
    <p class="form-intro">Enter the mill’s response. Freight, duty and licence values are per metre in {form.costing.currency||form.profile.garment_currency||'the costing currency'}.</p>
    <EnquiryFields fields={fabricFields} bind:values={form.fabric} {options} {busy} onadd={addOption}/>
    <label class="check"><input type="checkbox" bind:checked={form.fabric.tax_recoverable} disabled={busy}/>Input GST is recoverable — show it separately and exclude it from landed cost.</label>
    <div class="total-strip"><span>Total lead time</span><strong>{Number(form.fabric.ex_mill_days||0)+Number(form.fabric.transit_days||0)} days</strong><span>Ex-mill + transit</span>{#if arrival(form.fabric)}<strong>Expected factory arrival: {dates(arrival(form.fabric))}</strong>{/if}</div>
   {:else if mode==='cost'}
    <p class="form-intro">Enter component costs per garment. Percentages apply to base cost; commission applies to the subtotal after those additions.</p>
    <EnquiryFields fields={costFields.filter(f=>!['special_trims','labels','pocketing','fusing','general_trims','washing','embroidery'].includes(f.key))} bind:values={form.costing} {options} {busy} onadd={addOption}/>
    <div class="section-heading"><div><h3>Itemised trims & value additions</h3><p>Add special trims, labels, washing or embroidery only when needed.</p></div><button class="button secondary" type="button" disabled={busy||form.costing.components.length>=100} onclick={()=>{form.costing.components.push({category:'Special trims',description:'',quantity:1,unit_price:'',currency:form.costing.currency,exchange_rate:''});preview=null}}><Plus size={16}/>Add item</button></div>
    {#each form.costing.components as item,i}<div class="component-row"><label>Category<select bind:value={item.category} disabled={busy}>{#each ['Special trims','Labels','Pocketing','Fusing / lining','General trims','Washing','Embroidery','Other'] as value}<option>{value}</option>{/each}</select></label><label>Description<input bind:value={item.description} required maxlength="2000" disabled={busy}/></label><label>Qty / garment<input type="number" min="0.000001" step="0.000001" bind:value={item.quantity} required disabled={busy}/></label><label>Unit price<input type="number" min="0" step="0.000001" bind:value={item.unit_price} required disabled={busy}/></label><label>Currency<select bind:value={item.currency} required disabled={busy}>{#each options('currency') as value}<option>{value}</option>{/each}</select></label><label>Exchange rate to {form.costing.currency}<input type="number" min="0.000001" step="0.000001" bind:value={item.exchange_rate} required disabled={busy||item.currency===form.costing.currency}/></label><button type="button" class="button secondary" disabled={busy} aria-label={'Remove component '+(i+1)} onclick={()=>{form.costing.components.splice(i,1);preview=null}}><Trash2 size={17}/></button></div>{/each}
    <div class="preview-action"><button class="button secondary" type="button" disabled={busy} onclick={calculate}>Calculate preview</button><span>Preview does not save changes.</span></div>
    {#if preview}<div class="calculation-grid">{#each costEntries(preview) as [key,value]}<div class:cost-total={key==='cost_per_piece'||key==='total_cost'}><span>{calcLabels[key]||key}</span><strong>{num(value)}{key==='required_metres'?' m':''}</strong></div>{/each}</div>{/if}
   {:else if mode==='review'}
    <EnquiryFields fields={enquiryFields.filter(f=>['consumption','garment_delivery_date','fabric_sailing_date','garment_value','quoted_price','final_price','quotation_date','quotation_email','negotiation_note'].includes(f.key))} bind:values={form.profile} {options} {busy} onadd={addOption}/>
    <label class="review-note">Reason for correction<textarea bind:value={form.note} required maxlength="2000" rows="3" disabled={busy}></textarea></label>
   {:else if mode==='order'}
    <p class="form-intro">This PO uses the approved price and buyer. It enters the existing PO approval and production flow.</p>
    <div class="link-fields"><label>Buyer PO number<input bind:value={form.po} maxlength="60" required disabled={busy}/></label><label>Production category<select bind:value={form.product} required disabled={busy}>{#each ['Suits','Trousers','Shirts','General'] as product}<option>{product}</option>{/each}</select></label><label>Quantity (pieces)<input type="number" min="1" max="10000000" step="1" bind:value={form.quantity} required disabled={busy}/></label><label>Ex-factory date<input type="date" bind:value={form.due_date} required disabled={busy}/></label></div>
    <div class="total-strip"><span>Approved price: {num(form.profile.final_price)} {form.profile.garment_currency} / piece</span><span>Target consumption: {num(Number(form.profile.consumption||0)*.95)} m / piece</span></div>
   {/if}
  </div>
  <footer class="editor-footer"><button type="button" class="button secondary" disabled={busy} onclick={closeForm}>Cancel</button><button class="button primary" disabled={busy}>{busy?'Saving…':mode==='order'?'Create PO':mode==='new'?'Save enquiry draft':mode==='fabric'?'Save fabric response':mode==='cost'?'Save costing':'Save changes'}</button></footer>
 </form>
 {:else if detail}
 {@const r=detail.record}{@const p=r.profile}{@const f=r.fabric}{@const c=r.costing||{}}
 <header class="record-heading"><div><button class="back-link" disabled={busy} onclick={back}><ArrowLeft size={16}/>Enquiry register</button><h2 id="enquiry-detail-title" tabindex="-1">{ref(r.id)}{#if r.booking_number}<span> · {booking(r.booking_number)}</span>{/if}</h2><p>{r.buyer_name} · {p.brand} · {p.product}</p></div><div class="actions"><span class="status" class:approved={['Approved','Booked'].includes(r.status)}>{r.status}</span><a class="button secondary" href={'/api/enquiries/'+r.id+'/export'}><Download size={16}/>Export</a></div></header>
 {#if error}<p class="form-error" role="alert">{error}</p>{/if}{#if notice}<p class="saved-notice" role="status">{notice}</p>{/if}
 <div class="record-actions">
 {#if data?.can_create&&editable}<button class="button secondary" disabled={busy} id="enquiry-edit-edit" onclick={()=>edit('edit')}>Edit enquiry</button><button class="button secondary" disabled={busy} onclick={()=>act('request_fabric')}>Request fabric response</button>{/if}
 {#if data?.can_fabric&&['Fabric requested','Costing'].includes(r.status)}<button class="button primary" disabled={busy} id="enquiry-edit-fabric" onclick={()=>edit('fabric')}>Add fabric response</button>{/if}
 {#if data?.can_edit_cost&&editable}<button class="button primary" disabled={busy} id="enquiry-edit-cost" onclick={()=>edit('cost')}>Open costing</button>{/if}
 {#if data?.can_create&&editable}<button class="button primary" disabled={busy} onclick={()=>act('submit')}>Submit to MD</button>{/if}
 {#if (data?.can_create||data?.can_review)&&r.status==='Approved'}<button class="button primary" disabled={busy} onclick={()=>act('book')}>Generate booking</button>{/if}
 {#if data?.can_orders&&r.status==='Booked'}<button class="button primary" disabled={busy} id="enquiry-edit-order" onclick={()=>edit('order')}>Create production PO</button>{/if}
 </div>
 {#if r.review_note}<p class="review-message"><strong>Review note:</strong> {r.review_note}</p>{/if}
 {#if data?.can_review&&r.status==='Submitted'}<section class="review-panel"><h3>MD review</h3><p>Check the enquiry, attachments and costing before approval.</p><label>Review note<textarea bind:value={review} rows="2" maxlength="2000" disabled={busy}></textarea></label><div class="actions"><button class="button primary" disabled={busy} onclick={()=>act('approve')}>Approve enquiry</button><button class="button secondary" disabled={busy||!review.trim()} onclick={()=>act('return')}>Request changes</button><button class="button secondary" disabled={busy} id="enquiry-edit-review" onclick={()=>edit('review')}>Correct consumption / price / delivery</button></div></section>{/if}
 <section class="record-section"><h3>Enquiry details</h3><dl class="read-grid"><div><dt>Raised by</dt><dd>{r.merchant}</dd></div>{#if r.development_code}<div><dt>ET / EST</dt><dd>{r.development_code}</dd></div>{/if}{#if r.material_code}<div><dt>ETF / ESF</dt><dd>{r.material_code}</dd></div>{/if}{#each enquiryFields as field}{#if p[field.key]!==''&&p[field.key]!=null}<div class:wide={field.type==='textarea'}><dt>{field.label}</dt><dd>{p[field.key]}</dd></div>{/if}{/each}</dl></section>
 <section class="record-section"><div class="section-heading"><h3>Colour-wise requirement</h3><strong>{num(qty(r.colours),0)} pieces</strong></div><div class="table-scroll"><table><thead><tr><th>Colour</th><th>Buyer colour code</th><th class="numeric">Pieces</th><th class="numeric">Fabric required (m)</th></tr></thead><tbody>{#each r.colours as colour}<tr><td>{colour.colour}</td><td>{colour.buyer_colour_code||'—'}</td><td class="numeric">{num(colour.quantity,0)}</td><td class="numeric">{num(colour.quantity*Number(p.consumption||0),3)}</td></tr>{/each}</tbody><tfoot><tr><th colspan="2">Total</th><th class="numeric">{num(qty(r.colours),0)}</th><th class="numeric">{num(qty(r.colours)*Number(p.consumption||0),3)}</th></tr></tfoot></table></div></section>
 <section class="record-section"><h3>Fabric department response</h3>{#if f.price!=null}<dl class="read-grid">{#each fabricFields as field}{#if f[field.key]!==''&&f[field.key]!=null}<div class:wide={field.type==='textarea'}><dt>{field.label}</dt><dd>{f[field.key]}</dd></div>{/if}{/each}<div><dt>Total lead time</dt><dd>{Number(f.ex_mill_days||0)+Number(f.transit_days||0)} days</dd></div><div><dt>Expected factory arrival</dt><dd>{dates(arrival(f))}</dd></div><div><dt>Input GST recoverable</dt><dd>{f.tax_recoverable?'Yes':'No'}</dd></div></dl>{:else}<p class="muted">No response yet. Request the fabric price, MOQ and lead time from sourcing.</p>{/if}</section>
 {#if data?.can_cost}<section class="record-section"><div class="section-heading"><h3>Open costing</h3><strong>{c.currency||p.garment_currency}</strong></div>{#if r.calculation_error}<p class="form-error">{r.calculation_error}</p>{/if}<dl class="read-grid">{#each costFields as field}{#if c[field.key]!==''&&c[field.key]!=null}<div><dt>{field.label}</dt><dd>{c[field.key]}</dd></div>{/if}{/each}</dl>{#if c.components?.length}<div class="table-scroll component-summary"><table><thead><tr><th>Category / description</th><th>Qty / garment</th><th>Unit price</th><th>Currency</th><th>Exchange rate</th></tr></thead><tbody>{#each c.components as item}<tr><td>{item.category} · {item.description}</td><td>{item.quantity}</td><td>{item.unit_price}</td><td>{item.currency}</td><td>{item.currency===c.currency?'1':item.exchange_rate}</td></tr>{/each}</tbody></table></div>{/if}{#if c.currency&&r.calculation}<div class="calculation-grid">{#each costEntries(r.calculation) as [key,value]}<div class:cost-total={key==='cost_per_piece'||key==='total_cost'}><span>{calcLabels[key]||key}</span><strong>{num(value)}</strong></div>{/each}</div>{/if}</section>{/if}
 <section class="record-section"><h3>Documents</h3><ul class="document-list">{#each detail.files as file}<li><FileText size={17}/><a href={'/api/enquiry-files/'+file.id}>{file.category} · {file.name}{#if file.order_id} · {detail.orders.find((o:Row)=>o.id===file.order_id)?.po||'Linked PO'}{/if}</a></li>{:else}<li>No documents attached.</li>{/each}</ul>{#if canAttach}<div class="link-fields">{#if proofOnly}<label>Production PO for purchase proof<select bind:value={proofOrder} required disabled={busy}><option value="">Choose linked PO</option>{#each detail.orders as order}<option value={String(order.id)}>{order.po}</option>{/each}</select></label>{:else}<label>Document category<select bind:value={category} disabled={busy}>{#each (data?.can_create?['Buyer email','CAD','Specification','Buyer confirmation','Other']:[]).concat(data?.can_fabric&&data?.supplier_details?['Supplier quotation']:[]) as item}<option>{item}</option>{/each}</select></label>{/if}<label>{proofOnly?'Attach purchase proof (10 MB each)':'Attach files (10 MB each)'}<input type="file" multiple accept=".eml,.pdf,.docx,.xlsx,.csv,.txt,.png,.jpg,.jpeg,.dxf,.zip" disabled={busy||(proofOnly&&!proofOrder)} onchange={upload}/></label></div>{/if}</section>
 <section class="record-section"><h3>Production POs</h3><div class="table-scroll"><table><thead><tr><th>PO</th><th>Quantity</th><th>Ex-factory</th><th>Approval</th><th>Stage</th></tr></thead><tbody>{#each detail.orders as order}<tr><td>{order.po}</td><td>{num(order.quantity,0)}</td><td>{dates(order.due_date)}</td><td>{order.approval}</td><td>{order.stage}</td></tr>{:else}<tr><td colspan="5">{r.status==='Booked'?'No POs linked yet.':'POs can be created after booking approval.'}</td></tr>{/each}</tbody></table></div></section>
 <section class="record-section"><h3>Linked material purchases</h3><p class="muted">Purchases linked to these production POs stay traceable to this booking for supporting documents.</p><div class="table-scroll"><table><thead><tr><th>Purchase reference</th><th>Production PO</th><th>Quantity</th><th>Status</th></tr></thead><tbody>{#each detail.purchases||[] as purchase}<tr><td>{purchase.reference}</td><td>{purchase.po}</td><td>{num(purchase.quantity_hundredths/100,2)}</td><td>{purchase.status}</td></tr>{:else}<tr><td colspan="4">No linked purchases yet.</td></tr>{/each}</tbody></table></div></section><section class="record-section"><h3>Revision history</h3><ol class="history-list">{#each detail.history as item}<li><div><strong>{item.action}</strong><small>{item.actor} · {new Date(item.created_at).toLocaleString('en-GB')}</small></div><button class="text-button" disabled={busy} onclick={()=>history(item.id)}>View revision</button></li>{/each}</ol>{#if past}<div class="revision"><div class="section-heading"><h4>Revision from {new Date(past.created_at).toLocaleString('en-GB')}</h4><button class="button secondary" onclick={()=>past=null}>Close revision</button></div><p>{past.action} · {past.snapshot.status}</p><dl class="read-grid">{#each enquiryFields as field}{#if past.snapshot.profile?.[field.key]}<div><dt>{field.label}</dt><dd>{past.snapshot.profile[field.key]}</dd></div>{/if}{/each}{#each fabricFields as field}{#if past.snapshot.fabric?.[field.key]}<div><dt>{field.label}</dt><dd>{past.snapshot.fabric[field.key]}</dd></div>{/if}{/each}{#each costFields as field}{#if past.snapshot.costing?.[field.key]}<div><dt>{field.label}</dt><dd>{past.snapshot.costing[field.key]}</dd></div>{/if}{/each}</dl><h4>Colours & quantities</h4>{#each past.snapshot.colours||[] as colour}<p>{colour.colour} · {colour.buyer_colour_code||'No buyer code'} · {colour.quantity} pieces</p>{/each}{#if past.snapshot.costing?.components?.length}<h4>Itemised costs</h4>{#each past.snapshot.costing.components as item}<p>{item.category} · {item.description} · {item.quantity} × {item.unit_price} {item.currency}{#if item.currency!==past.snapshot.costing.currency} · rate {item.exchange_rate}{/if}</p>{/each}{/if}</div>{/if}</section>
 {#if data?.can_review&&['Approved','Booked'].includes(r.status)&&!detail.orders.length}<section class="record-section"><h3>Amendment</h3><label>Reason for reopening<textarea bind:value={review} rows="2" maxlength="2000" disabled={busy}></textarea></label><button class="button secondary" disabled={busy||!review.trim()} onclick={()=>act('amend')}>Reopen for changes</button></section>{/if}
 {:else}
 <header class="register-heading"><div><h2>Enquiry register</h2><p>Buyer request → fabric response → costing → MD review → booking.</p></div><div class="actions"><button class="button secondary" disabled={busy} onclick={()=>run(load)}><RefreshCw size={16}/>Refresh</button>{#if data?.can_create}<button class="button primary" disabled={busy} id="enquiry-new" onclick={fresh}><Plus size={17}/>New enquiry</button>{/if}</div></header>
 {#if error}<p class="form-error" role="alert">{error}</p>{/if}
 <div class="register-tools"><label class="search"><Search size={18}/><input aria-label="Search enquiries" placeholder="Search enquiry, booking, buyer or style" bind:value={search}/></label><label>Status<select bind:value={status}>{#each ['All','Draft','Fabric requested','Costing','Submitted','Changes requested','Approved','Booked'] as item}<option>{item}</option>{/each}</select></label><span class="result-count">{records.length} enquiries{#if data?.records?.length>=data?.record_limit} · latest {data?.record_limit}{/if}</span></div>
 <div class="table-scroll"><table><thead><tr><th>Enquiry / booking</th><th>Buyer & brand</th><th>Style / product</th><th>Raised by</th><th class="numeric">Quantity</th><th>Delivery</th><th>Status</th></tr></thead><tbody>{#each records as record}<tr><td><button id={'enquiry-open-'+record.id} class="text-button reference-link" aria-label={'Open '+ref(record.id)} disabled={busy} onclick={()=>open(record.id)}>{ref(record.id)}</button>{#if record.booking_number}<small>{booking(record.booking_number)}</small>{/if}</td><td>{record.buyer_name}<small>{record.profile.brand}</small></td><td>{record.profile.buyer_style||'New style'}<small>{record.profile.product} · {record.profile.sale_type}</small></td><td>{record.merchant}</td><td class="numeric">{num(qty(record.colours),0)}</td><td>{dates(record.profile.garment_delivery_date)}</td><td><span class="status" class:approved={['Approved','Booked'].includes(record.status)}>{record.status}</span></td></tr>{:else}<tr><td colspan="7"><div class="empty-enquiries"><FileText size={28}/><h3>{busy?'Loading enquiries…':search||status!=='All'?'No matching enquiries':'No enquiries yet'}</h3><p>{search||status!=='All'?'Change the search or status filter.':data?.can_create?'Create an enquiry to begin the fabric and costing review.':'Enquiries assigned to your company and buyers will appear here.'}</p></div></td></tr>{/each}</tbody></table></div>
 {/if}
</section>
