peat(3,minmax(0,1fr));gap:16px;padding:20px 0;border-bottom:1px solid #cbdad2}.component-row>button{justify-self:end;grid-column:-2/-1}.component-summary{margin-top:22px}.colour-row{display:grid;grid-template-columns:1.2fr 1fr 1fr 1fr auto;gap:16px;align-items:end;padding:16px 0;border-bottom:1px solid #cbdad2}.metres{align-self:center}.metres span{display:block;font-size:12px;color:#47616f;margin-bottom:8px}.metres strong{font-variant-numeric:tabular-nums}.editor-body>.section-heading{margin-top:34px}.total-strip{display:flex;gap:24px;justify-content:flex-end;flex-wrap:wrap;padding:18px;margin-top:20px;background:#dcece5;border-radius:10px;font-variant-numeric:tabular-nums}.form-intro{line-height:1.6;max-width:75ch;margin:0 0 24px;color:#365260}.check{display:flex;flex-direction:row;align-items:center;margin:24px 0;line-height:1.5}.check input{width:19px;height:19px;min-height:19px;flex-shrink:0}.preview-action{display:flex;gap:15px;align-items:center;margin:24px 0}.preview-action span{font-size:13px;color:#47616f}.calculation-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;margin-top:24px;background:#f1f6f5;border-radius:12px;overflow:hidden;font-variant-numeric:tabular-nums}.calculation-grid>div{padding:18px;border-bottom:1px solid #d5e2e0}.calculation-grid span{display:block;font-size:12px;color:#47616f;margin-bottom:8px}.calculation-grid strong{font-size:20px}.calculation-grid .cost-total{background:#d7ece6}.cost-total span{color:#1b564f}.review-note{margin-top:24px}.document-list{list-style:none;padding:0;display:grid;gap:12px}.document-list li{display:flex;align-items:center;gap:9px;overflow-wrap:anywhere}.document-list a{color:#176d67;text-underline-offset:3px}.history-list{list-style:none;padding:0;margin:0}.history-list li{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:13px 0;border-bottom:1px solid #d8e4e6}.history-list small{display:block;color:#47616f;margin-top:6px}.revision{background:#f0f5f3;padding:22px;border-radius:12px;margin-top:20px}.record-section>button{margin-top:14px}::selection{background:#c6e5df;color:#132b40}@media(max-width:1150px){.read-grid,.link-fields,.calculation-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.register-heading,.record-heading{align-items:flex-start;flex-wrap:wrap}.colour-row{grid-template-columns:1fr 1fr 1fr}.colour-row .metres{grid-column:1/3}.enquiries{padding:20px}.enquiry-editor{margin:-20px}.register-tools{flex-wrap:wrap}.search{min-width:300px}.enquiry-heading{padding:16px 22px}.editor-body{padding:24px 22px}}
